/**
 * The "Generated by an AI agent" line on every form that takes a connector's
 * credentials (ConnectorGeneratedByNote.tsx). The #1330 live test found it on
 * /connections/new only: the /connectors Configure dialog holds a catalog-list
 * record, which has no generated_by, and never asked for the single read.
 */

import { readFileSync, readdirSync, statSync } from "node:fs"
import { join, relative, resolve } from "node:path"
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest"
import { cleanup, render, screen, waitFor } from "@testing-library/react"
import "@testing-library/jest-dom"

// A plain stub, not vi.fn: on vitest 4.1 a vi.fn cleared in beforeEach whose
// promise rejected failed the test, though the component handled the
// rejection.
const reads: string[] = []
let reply: () => Promise<unknown> = () => new Promise(() => {})
vi.mock("@/lib/api/mcp-connectors", () => ({
  fetchMCPConnector: (name: string) => {
    reads.push(name)
    return reply()
  },
}))

import { ConnectorGeneratedByNote, generatedByLine } from "@/components/connectors/ConnectorGeneratedByNote"

const generated = { generated_by_agent: true, generated_at: "2026-10-01T17:49:43Z", by: "Ask rsync.ai" }

beforeEach(() => {
  reads.length = 0
  reply = () => new Promise(() => {})
})
afterEach(() => cleanup())

describe("ConnectorGeneratedByNote", () => {
  it("shows the line from the single read's generated_by, without another request", () => {
    render(<ConnectorGeneratedByNote connector={{ name: "acme-crm", generated_by: generated }} lookUp />)
    expect(screen.getByTestId("connector-generated-by")).toHaveTextContent(
      /^Generated by an AI agent \(Ask rsync\.ai\) on .+\. Review it before you give it credentials\.$/,
    )
    expect(reads).toEqual([])
  })

  it("reads the connector when the record came from the catalog list", async () => {
    reply = async () => ({ name: "acme-crm", generated_by: generated })
    render(<ConnectorGeneratedByNote connector={{ name: "acme-crm" }} lookUp />)
    await waitFor(() => expect(screen.getByTestId("connector-generated-by")).toBeInTheDocument())
    expect(reads).toEqual(["acme-crm"])
  })

  it("shows nothing for a connector no agent generated", async () => {
    let settled = false
    reply = async () => {
      settled = true
      return { name: "postgresql" }
    }
    render(<ConnectorGeneratedByNote connector={{ name: "postgresql" }} lookUp />)
    await waitFor(() => expect(settled).toBe(true))
    expect(screen.queryByTestId("connector-generated-by")).toBeNull()
  })

  it("leaves the form as it was when the read fails", async () => {
    let settled = false
    reply = async () => {
      settled = true
      throw new Error("catalog unreachable")
    }
    render(<ConnectorGeneratedByNote connector={{ name: "acme-crm" }} lookUp />)
    await waitFor(() => expect(settled).toBe(true))
    expect(screen.queryByTestId("connector-generated-by")).toBeNull()
  })

  it("does not read unless asked: the single read already says it all", () => {
    render(<ConnectorGeneratedByNote connector={{ name: "postgresql" }} />)
    expect(reads).toEqual([])
  })

  it("leaves out who when the run was another workspace's", () => {
    expect(generatedByLine({ generated_by_agent: true, generated_at: "not a date" })).toBe(
      "Generated by an AI agent. Review it before you give it credentials.",
    )
  })
})

// The class: a form that takes a connector's credentials without the line. Each
// one renders GenericConnectorForm, so every file that does must render the note.
describe("every credential form shows the note", () => {
  it("renders ConnectorGeneratedByNote wherever GenericConnectorForm is rendered", () => {
    const src = resolve(process.cwd(), "src")
    const files: string[] = []
    const walk = (dir: string) => {
      for (const name of readdirSync(dir)) {
        const path = join(dir, name)
        if (statSync(path).isDirectory()) {
          if (name !== "__tests__" && name !== "node_modules") walk(path)
        } else if (path.endsWith(".tsx")) {
          files.push(path)
        }
      }
    }
    walk(src)
    const forms = files.filter((f) => readFileSync(f, "utf8").includes("<GenericConnectorForm"))
    expect(forms.length).toBeGreaterThanOrEqual(4)
    const missing = forms.filter((f) => !readFileSync(f, "utf8").includes("<ConnectorGeneratedByNote"))
    expect(missing.map((f) => relative(src, f))).toEqual([])
  })
})
